INSERT INTO "documents" VALUES(187,'act716','Wildlife Conservation Act 2010 (Act 716)','The Wildlife Conservation Act 2010 (Act 716) protects Malaysian wildlife. It applies to Peninsular Malaysia and the Federal Territory of Labuan, and classifies species as Protected or Totally Protected. Totally Protected species receive the highest legal protection.','https://archive.data.gov.my/data/dataset/bilangan-spesies-hidupan-liar-yang-tersenarai-di-bawah-akta-pemuliharaan-hidupan-liar-2010-akta-716','Creative Commons Attribution (legacy data.gov.my)');
INSERT INTO "documents" VALUES(188,'act716','Malayan Porcupine','Malayan Porcupine (Hystrix brachyura) 中文名 马来豪猪 马来名 Landak Raya is listed in the First Schedule of the Wildlife Conservation Act 2010 (Act 716), so it is Protected under Malaysian law. 在马来西亚《2010年野生动物保护法》(Act 716) 中列入第一附表，属受保护物种。','https://archive.data.gov.my/data/dataset/bilangan-spesies-hidupan-liar-yang-tersenarai-di-bawah-akta-pemuliharaan-hidupan-liar-2010-akta-716','Creative Commons Attribution (legacy data.gov.my)');
INSERT INTO "documents" VALUES(189,'act716','Sambar Deer','Sambar Deer (Rusa unicolor) 中文名 水鹿 马来名 Rusa Sambar is listed in the First Schedule of the Wildlife Conservation Act 2010 (Act 716), so it is Protected under Malaysian law. 在马来西亚《2010年野生动物保护法》(Act 716) 中列入第一附表，属受保护物种。','https://archive.data.gov.my/data/dataset/bilangan-spesies-hidupan-liar-yang-tersenarai-di-bawah-akta-pemuliharaan-hidupan-liar-2010-akta-716','Creative Commons Attribution (legacy data.gov.my)');
