INSERT INTO "locations" VALUES('loc_bukit_gasing','Bukit Gasing Forest Reserve','Forest reserve',3.0964,101.65,1,'A small, family-friendly green lung with forest trails close to the city.','["Trails", "Parking", "Rest area"]','7:00–10:00 AM',1.2,'Nearby, with gentle trails and regular butterfly and bird sightings.');
INSERT INTO "locations" VALUES('loc_frim','FRIM (Forest Research Institute Malaysia)','Forest reserve',3.24,101.65,1,'A research forest with a canopy walkway and rich biodiversity.','["Canopy walkway", "Trails", "Parking", "Restroom"]','8:00–11:00 AM',12.0,'Easy access to a real rainforest canopy and frequent wildlife observation reports.');
INSERT INTO "locations" VALUES('loc_taman_negara','Taman Negara National Park','National park',4.4,102.4,1,'One of the world''s oldest rainforests, home to elephants, tapirs and hornbills.','["Guided trails", "River trips", "Accommodation"]','March–September',180.0,'For families wanting a deeper rainforest experience with guided support.');
INSERT INTO "locations" VALUES('loc_kuala_selangor','Kuala Selangor Nature Park','Nature park',3.35,101.25,1,'Mangrove forest with resident and migratory birds and fireflies at night.','["Mangrove boardwalk", "Bird hides", "Parking"]','5:00–9:00 PM (fireflies)',65.0,'A safe boardwalk for watching wetland birds and reptiles.');
INSERT INTO "locations" VALUES('loc_bako','Bako National Park','National park',1.72,110.46,1,'Sarawak''s oldest park, famous for proboscis monkeys and diverse habitats.','["Trails", "Boat transfer", "Lodging"]','April–October',950.0,'One of the best places to see proboscis monkeys in the wild.');
INSERT INTO "locations" VALUES('loc_cherating','Cherating Turtle Sanctuary','Sanctuary',4.13,103.39,1,'A beach sanctuary protecting nesting green sea turtles.','["Visitor centre", "Guided night watch", "Parking"]','July–October (nesting season)',260.0,'A supervised way to learn about sea-turtle conservation.');
INSERT INTO "locations" VALUES('loc_per_paya_indah','Paya Indah Wetlands','Wetland reserve',2.8604,101.6288,1,'An official PERHILITAN eco-tourism wetland reserve rich in birdlife.','["Wetland trails", "Visitor centre", "Parking"]','8:00–11:00 AM',45.0,'Boardwalks and hides make it easy to watch wetland birds safely.');
INSERT INTO "locations" VALUES('loc_per_kuala_koh','Taman Negara Kelantan, Kuala Koh','National park',4.850153,102.436522,1,'A quieter gateway into the Taman Negara rainforest in Kelantan.','["Guided trails", "River"]','March–September',320.0,'Less crowded rainforest access with guided river and forest trails.');
INSERT INTO "locations" VALUES('loc_per_tn_penang','Taman Negara Pulau Pinang','National park',5.448,100.1932,1,'One of the world''s smallest national parks, where forest meets the coast.','["Trails", "Beach"]','March–October',300.0,'Coastal trails and accessible rainforest in a compact park.');
INSERT INTO "locations" VALUES('loc_per_merapoh','Taman Negara Pahang, Sg Relau, Merapoh','National park',4.6807,102.0562,1,'Western gateway to Taman Negara Pahang, known for caves and forest trails.','["Trails", "Caves"]','March–September',210.0,'Quiet trails and limestone caves with family-friendly routes.');
INSERT INTO "locations" VALUES('loc_per_tanjung_mentong','Taman Negara Terengganu, Tanjung Mentong','National park',5.0,102.8,1,'Eastern entrance to Taman Negara along Lake Kenyir.','["River trips", "Trails"]','March–September',280.0,'Boat access across Lake Kenyir to the rainforest.');
INSERT INTO "locations" VALUES('loc_per_kuala_gandah','Kuala Gandah Elephant Conservation Centre','Conservation centre',3.5923,102.142819,1,'PERHILITAN''s national Asian elephant conservation centre.','["Visitor centre", "Guided talks"]','Open daily; morning sessions',95.0,'A supervised way to learn about Asian elephant conservation.');
INSERT INTO "locations" VALUES('loc_per_kuala_tahan','Taman Negara Pahang, Kuala Tahan','National park',4.383333,102.4,1,'The main gateway to Taman Negara, home to the famous canopy walkway.','["Canopy walkway", "Guided trails", "River trips", "Accommodation"]','March–September',180.0,'The classic family rainforest experience with a canopy walkway.');
INSERT INTO "locations" VALUES('loc_per_tasek_bera','Tapak RAMSAR Tasek Bera','RAMSAR wetland',3.8167,102.4167,1,'Malaysia''s first RAMSAR wetland, a protected freshwater lake system.','["Boat trips", "Visitor centre"]','Dry season (March–September)',150.0,'Guided boat trips through a protected freshwater wetland.');
