INSERT INTO "quizzes" VALUES(1,'sp_common_mormon',1,'[{"question": "What do Common Mormon caterpillars mainly eat?", "question_zh": "\u7389\u5e26\u51e4\u8776\u7684\u5e7c\u866b\u4e3b\u8981\u5403\u4ec0\u4e48\uff1f", "options": ["Nectar", "Citrus leaves", "Fruits", "Insects"], "options_zh": ["\u82b1\u871c", "\u67d1\u6a58\u6811\u53f6", "\u679c\u5b9e", "\u6606\u866b"], "correct_index": 1, "explanation": "Their caterpillars feed on leaves of citrus-family plants.", "explanation_zh": "\u5b83\u4eec\u7684\u5e7c\u866b\u4ee5\u67d1\u6a58\u7c7b\u690d\u7269\u7684\u53f6\u5b50\u4e3a\u98df\u3002"}, {"question": "Where does the Common Mormon butterfly live?", "question_zh": "\u7389\u5e26\u51e4\u8776\u751f\u6d3b\u5728\u54ea\u91cc\uff1f", "options": ["Only deep forest", "Gardens, parks and forest edges", "Only beaches", "Caves"], "options_zh": ["\u53ea\u5728\u5bc6\u6797\u6df1\u5904", "\u82b1\u56ed\u3001\u516c\u56ed\u548c\u68ee\u6797\u8fb9\u7f18", "\u53ea\u5728\u6d77\u6ee9", "\u6d1e\u7a74\u91cc"], "correct_index": 1, "explanation": "It is a common garden and park butterfly.", "explanation_zh": "\u5b83\u662f\u82b1\u56ed\u548c\u516c\u56ed\u91cc\u5e38\u89c1\u7684\u8774\u8776\u3002"}, {"question": "How does some females protect themselves?", "question_zh": "\u90e8\u5206\u96cc\u8776\u5982\u4f55\u4fdd\u62a4\u81ea\u5df1\uff1f", "options": ["By flying at night", "By copying a poisonous butterfly''s look", "By hiding in water", "By digging"], "options_zh": ["\u591c\u95f4\u98de\u884c", "\u6a21\u4eff\u6709\u6bd2\u8774\u8776\u7684\u5916\u8c8c", "\u8eb2\u8fdb\u6c34\u91cc", "\u6316\u6d1e"], "correct_index": 1, "explanation": "Mimicry makes predators avoid them.", "explanation_zh": "\u62df\u6001\u80fd\u8ba9\u5929\u654c\u907f\u5f00\u5b83\u4eec\u3002"}]');
INSERT INTO "quizzes" VALUES(2,'sp_tailed_jay',1,'[{"question": "What do adult Tailed Jay butterflies drink?", "question_zh": "\u7edf\u5e05\u9752\u51e4\u8776\u7684\u6210\u866b\u559d\u4ec0\u4e48\uff1f", "options": ["Tree sap only", "Flower nectar", "Water", "Honeydew only"], "options_zh": ["\u53ea\u559d\u6811\u6db2", "\u82b1\u871c", "\u6c34", "\u53ea\u559d\u871c\u9732"], "correct_index": 1, "explanation": "Adults feed on nectar from flowers.", "explanation_zh": "\u6210\u866b\u4ee5\u82b1\u871c\u4e3a\u98df\u3002"}, {"question": "Why is the Tailed Jay hard to photograph?", "question_zh": "\u4e3a\u4ec0\u4e48\u7edf\u5e05\u9752\u51e4\u8776\u5f88\u96be\u62cd\u7167\uff1f", "options": ["It is slow", "It flies very fast", "It only comes out at night", "It is invisible"], "options_zh": ["\u5b83\u5f88\u6162", "\u5b83\u98de\u5f97\u5f88\u5feb", "\u5b83\u53ea\u5728\u591c\u95f4\u51fa\u73b0", "\u5b83\u662f\u9690\u5f62\u7684"], "correct_index": 1, "explanation": "It is one of the fastest-flying butterflies.", "explanation_zh": "\u5b83\u662f\u98de\u884c\u6700\u5feb\u7684\u8774\u8776\u4e4b\u4e00\u3002"}, {"question": "What colour pattern does the Tailed Jay show?", "question_zh": "\u7edf\u5e05\u9752\u51e4\u8776\u662f\u4ec0\u4e48\u989c\u8272\u56fe\u6848\uff1f", "options": ["Green with black spots", "Red and yellow", "Plain white", "Blue stripes"], "options_zh": ["\u7eff\u8272\u5e26\u9ed1\u6591", "\u7ea2\u9ec4\u76f8\u95f4", "\u7eaf\u767d", "\u84dd\u8272\u6761\u7eb9"], "correct_index": 0, "explanation": "It is green with black spots.", "explanation_zh": "\u5b83\u662f\u7eff\u8272\u5e26\u9ed1\u6591\u7684\u3002"}]');
INSERT INTO "quizzes" VALUES(3,'sp_oriental_pied_hornbill',1,'[{"question": "What is a favourite food of the Oriental Pied Hornbill?", "question_zh": "\u51a0\u6591\u7280\u9e1f\u6700\u559c\u6b22\u7684\u98df\u7269\u662f\u4ec0\u4e48\uff1f", "options": ["Leaves", "Figs (fruit)", "Fish", "Bark"], "options_zh": ["\u6811\u53f6", "\u65e0\u82b1\u679c\uff08\u679c\u5b9e\uff09", "\u9c7c", "\u6811\u76ae"], "correct_index": 1, "explanation": "Hornbills love figs and other fruit.", "explanation_zh": "\u7280\u9e1f\u559c\u6b22\u65e0\u82b1\u679c\u7b49\u679c\u5b9e\u3002"}, {"question": "What does the female do while nesting?", "question_zh": "\u96cc\u9e1f\u5728\u7b51\u5de2\u65f6\u4f1a\u505a\u4ec0\u4e48\uff1f", "options": ["Migrates", "Seals herself inside a tree cavity", "Hunts far away", "Builds a grass nest"], "options_zh": ["\u8fc1\u5f99", "\u628a\u81ea\u5df1\u5c01\u5728\u6811\u6d1e\u91cc", "\u53bb\u8fdc\u5904\u6355\u730e", "\u7528\u8349\u7b51\u5de2"], "correct_index": 1, "explanation": "She seals herself in, leaving a gap to receive food.", "explanation_zh": "\u5b83\u4f1a\u628a\u81ea\u5df1\u5c01\u5728\u6d1e\u91cc\uff0c\u7559\u4e00\u4e2a\u5c0f\u53e3\u63a5\u6536\u98df\u7269\u3002"}, {"question": "What threatens hornbills?", "question_zh": "\u4ec0\u4e48\u5a01\u80c1\u7740\u7280\u9e1f\uff1f", "options": ["Too much rain", "Loss of forest and old nesting trees", "Cold weather", "Ocean currents"], "options_zh": ["\u96e8\u6c34\u592a\u591a", "\u68ee\u6797\u548c\u8001\u7b51\u5de2\u6811\u51cf\u5c11", "\u5929\u6c14\u5bd2\u51b7", "\u6d0b\u6d41"], "correct_index": 1, "explanation": "They need old trees with holes for nesting.", "explanation_zh": "\u5b83\u4eec\u9700\u8981\u6709\u6811\u6d1e\u7684\u8001\u6811\u6765\u7b51\u5de2\u3002"}]');
INSERT INTO "quizzes" VALUES(4,'sp_rhinoceros_hornbill',1,'[{"question": "Which state has the Rhinoceros Hornbill as its bird?", "question_zh": "\u54ea\u4e2a\u5dde\u4ee5\u9a6c\u6765\u7280\u9e1f\u4e3a\u5dde\u9e1f\uff1f", "options": ["Selangor", "Sarawak", "Penang", "Johor"], "options_zh": ["\u96ea\u5170\u83aa", "\u7802\u62c9\u8d8a", "\u69df\u57ce", "\u67d4\u4f5b"], "correct_index": 1, "explanation": "It is the state bird of Sarawak.", "explanation_zh": "\u5b83\u662f\u7802\u62c9\u8d8a\u5dde\u7684\u5dde\u9e1f\u3002"}, {"question": "What is the casque?", "question_zh": "\u76d4\u7a81\u662f\u4ec0\u4e48\uff1f", "options": ["A tail feather", "A bright structure on top of its bill", "A claw", "A nest"], "options_zh": ["\u4e00\u6839\u5c3e\u7fbd", "\u5599\u4e0a\u65b9\u7684\u9192\u76ee\u7ed3\u6784", "\u4e00\u53ea\u722a\u5b50", "\u4e00\u4e2a\u5de2"], "correct_index": 1, "explanation": "It has a large orange casque on its bill.", "explanation_zh": "\u5b83\u7684\u5599\u4e0a\u6709\u4e00\u4e2a\u6a59\u8272\u5927\u76d4\u7a81\u3002"}, {"question": "Why should you not share its exact nest location?", "question_zh": "\u4e3a\u4ec0\u4e48\u4e0d\u8be5\u516c\u5f00\u5b83\u7684\u786e\u5207\u5de2\u7a74\u4f4d\u7f6e\uff1f", "options": ["It is boring", "To protect it from hunting", "Nests move daily", "They are not real"], "options_zh": ["\u56e0\u4e3a\u65e0\u804a", "\u4e3a\u4e86\u4fdd\u62a4\u5b83\u514d\u53d7\u6355\u730e", "\u5de2\u6bcf\u5929\u90fd\u4f1a\u79fb\u52a8", "\u5b83\u4eec\u4e0d\u662f\u771f\u7684"], "correct_index": 1, "explanation": "Protecting nest sites helps vulnerable hornbills.", "explanation_zh": "\u4fdd\u62a4\u5de2\u7a74\u6709\u52a9\u4e8e\u4fdd\u62a4\u6613\u5371\u7684\u7280\u9e1f\u3002"}]');
INSERT INTO "quizzes" VALUES(5,'sp_asian_elephant',1,'[{"question": "What does an Asian Elephant use its trunk for?", "question_zh": "\u4e9a\u6d32\u8c61\u7528\u8c61\u9f3b\u505a\u4ec0\u4e48\uff1f", "options": ["Only drinking", "Smelling, drinking, greeting and picking up food", "Only fighting", "Nothing"], "options_zh": ["\u53ea\u7528\u6765\u559d\u6c34", "\u95fb\u3001\u559d\u6c34\u3001\u6253\u62db\u547c\u548c\u53d6\u98df", "\u53ea\u7528\u6765\u6253\u67b6", "\u4ec0\u4e48\u4e5f\u4e0d\u505a"], "correct_index": 1, "explanation": "The trunk is used for many tasks.", "explanation_zh": "\u8c61\u9f3b\u80fd\u505a\u5f88\u591a\u4e8b\u3002"}, {"question": "What is a main threat to Asian Elephants?", "question_zh": "\u4e9a\u6d32\u8c61\u9762\u4e34\u7684\u4e3b\u8981\u5a01\u80c1\u662f\u4ec0\u4e48\uff1f", "options": ["Snow", "Habitat loss and conflict with farms", "Too many trees", "Loud music"], "options_zh": ["\u4e0b\u96ea", "\u6816\u606f\u5730\u4e27\u5931\u548c\u4e0e\u519c\u7530\u7684\u51b2\u7a81", "\u6811\u592a\u591a", "\u97f3\u4e50\u592a\u5435"], "correct_index": 1, "explanation": "Forest loss brings elephants into conflict with people.", "explanation_zh": "\u68ee\u6797\u51cf\u5c11\u4f7f\u5927\u8c61\u4e0e\u4eba\u7c7b\u53d1\u751f\u51b2\u7a81\u3002"}, {"question": "What should you do if you meet a wild elephant?", "question_zh": "\u9047\u5230\u91ce\u8c61\u65f6\u5e94\u8be5\u600e\u4e48\u505a\uff1f", "options": ["Run toward it", "Keep far away and do not block its path", "Feed it", "Touch it"], "options_zh": ["\u671d\u5b83\u8dd1\u8fc7\u53bb", "\u4fdd\u6301\u5f88\u8fdc\u8ddd\u79bb\uff0c\u4e0d\u6321\u5b83\u7684\u8def", "\u5582\u5b83", "\u6478\u5b83"], "correct_index": 1, "explanation": "Keep your distance \u2014 elephants are wild animals.", "explanation_zh": "\u4fdd\u6301\u8ddd\u79bb\u2014\u2014\u5927\u8c61\u662f\u91ce\u751f\u52a8\u7269\u3002"}]');
INSERT INTO "quizzes" VALUES(6,'sp_malayan_tiger',1,'[{"question": "What is the Malayan Tiger''s conservation status?", "question_zh": "\u9a6c\u6765\u4e9a\u864e\u7684\u4fdd\u62a4\u7b49\u7ea7\u662f\u4ec0\u4e48\uff1f", "options": ["Not threatened", "Critically Endangered", "Least Concern", "Extinct"], "options_zh": ["\u65e0\u5371", "\u6781\u5371", "\u6613\u5371", "\u5df2\u706d\u7edd"], "correct_index": 1, "explanation": "It is Critically Endangered.", "explanation_zh": "\u5b83\u662f\u6781\u5371\u7269\u79cd\u3002"}, {"question": "What is unique about each tiger?", "question_zh": "\u6bcf\u53ea\u8001\u864e\u6709\u4ec0\u4e48\u72ec\u7279\u4e4b\u5904\uff1f", "options": ["Its stripe pattern", "Its eye colour", "Its tail length", "Its roar volume"], "options_zh": ["\u6761\u7eb9\u56fe\u6848", "\u773c\u775b\u989c\u8272", "\u5c3e\u5df4\u957f\u5ea6", "\u543c\u58f0\u5927\u5c0f"], "correct_index": 0, "explanation": "Stripe patterns are unique, like fingerprints.", "explanation_zh": "\u6761\u7eb9\u56fe\u6848\u72ec\u4e00\u65e0\u4e8c\uff0c\u5c31\u50cf\u6307\u7eb9\u3002"}, {"question": "Why should you never try to find a tiger?", "question_zh": "\u4e3a\u4ec0\u4e48\u6c38\u8fdc\u4e0d\u8be5\u53bb\u5bfb\u627e\u8001\u864e\uff1f", "options": ["It is fun", "They are rare and shy \u2014 approaching is unsafe for both you and the tiger", "They are friendly", "They are slow"], "options_zh": ["\u5f88\u597d\u73a9", "\u5b83\u4eec\u7a00\u6709\u800c\u5bb3\u7f9e\u2014\u2014\u9760\u8fd1\u5bf9\u4f60\u548c\u5b83\u90fd\u5f88\u5371\u9669", "\u5b83\u4eec\u5f88\u53cb\u597d", "\u5b83\u4eec\u5f88\u6162"], "correct_index": 1, "explanation": "Searching for tigers risks your safety and theirs.", "explanation_zh": "\u5bfb\u627e\u8001\u864e\u4f1a\u5371\u53ca\u4f60\u548c\u5b83\u7684\u5b89\u5168\u3002"}]');
INSERT INTO "quizzes" VALUES(7,'sp_malayan_tapir',1,'[{"question": "What pattern do baby tapirs have?", "question_zh": "\u9a6c\u6765\u8c98\u5e7c\u5d3d\u6709\u4ec0\u4e48\u56fe\u6848\uff1f", "options": ["Plain grey", "Stripes and spots", "Bright red", "No pattern"], "options_zh": ["\u7eaf\u7070\u8272", "\u6761\u7eb9\u548c\u6591\u70b9", "\u9c9c\u7ea2\u8272", "\u6ca1\u6709\u56fe\u6848"], "correct_index": 1, "explanation": "Babies have stripes and spots for camouflage.", "explanation_zh": "\u5e7c\u5d3d\u5e26\u6761\u7eb9\u548c\u6591\u70b9\u7528\u4e8e\u4f2a\u88c5\u3002"}, {"question": "What is a threat to tapirs?", "question_zh": "\u9a6c\u6765\u8c98\u9762\u4e34\u4ec0\u4e48\u5a01\u80c1\uff1f", "options": ["Road accidents and habitat loss", "Too much food", "Cold weather", "Volcanoes"], "options_zh": ["\u4ea4\u901a\u4e8b\u6545\u548c\u6816\u606f\u5730\u4e27\u5931", "\u98df\u7269\u592a\u591a", "\u5929\u6c14\u5bd2\u51b7", "\u706b\u5c71"], "correct_index": 0, "explanation": "Roads and forest loss harm tapirs.", "explanation_zh": "\u9053\u8def\u548c\u68ee\u6797\u51cf\u5c11\u4f1a\u4f24\u5bb3\u8c98\u3002"}, {"question": "What does a tapir mainly eat?", "question_zh": "\u9a6c\u6765\u8c98\u4e3b\u8981\u5403\u4ec0\u4e48\uff1f", "options": ["Meat", "Leaves, shoots and fruit", "Fish", "Insects only"], "options_zh": ["\u8089", "\u6811\u53f6\u3001\u5ae9\u679d\u548c\u679c\u5b9e", "\u9c7c", "\u53ea\u5403\u6606\u866b"], "correct_index": 1, "explanation": "Tapirs are plant-eaters.", "explanation_zh": "\u8c98\u662f\u690d\u98df\u52a8\u7269\u3002"}]');
INSERT INTO "quizzes" VALUES(8,'sp_sun_bear',1,'[{"question": "What mark does a Sun Bear have on its chest?", "question_zh": "\u9a6c\u6765\u718a\u80f8\u524d\u6709\u4ec0\u4e48\u6807\u8bb0\uff1f", "options": ["A star", "A pale horseshoe shape", "A triangle", "A circle"], "options_zh": ["\u661f\u661f", "\u6de1\u8272\u9a6c\u8e44\u5f62", "\u4e09\u89d2\u5f62", "\u5706\u5f62"], "correct_index": 1, "explanation": "It has a pale horseshoe-shaped mark.", "explanation_zh": "\u5b83\u80f8\u524d\u6709\u6de1\u8272\u9a6c\u8e44\u5f62\u6591\u7eb9\u3002"}, {"question": "What is the Sun Bear known for being?", "question_zh": "\u9a6c\u6765\u718a\u4ee5\u4ec0\u4e48\u8457\u79f0\uff1f", "options": ["The largest bear", "The world''s smallest bear", "The fastest bear", "A bird"], "options_zh": ["\u6700\u5927\u7684\u718a", "\u4e16\u754c\u4e0a\u6700\u5c0f\u7684\u718a", "\u6700\u5feb\u7684\u718a", "\u4e00\u79cd\u9e1f"], "correct_index": 1, "explanation": "It is the smallest bear species.", "explanation_zh": "\u5b83\u662f\u6700\u5c0f\u7684\u718a\u79cd\u3002"}, {"question": "Why should you never feed a sun bear?", "question_zh": "\u4e3a\u4ec0\u4e48\u7edd\u4e0d\u8981\u5582\u9a6c\u6765\u718a\uff1f", "options": ["It may become dependent and dangerous", "They only eat honey", "It is illegal to look at them", "They have no teeth"], "options_zh": ["\u5b83\u4f1a\u53d8\u5f97\u4f9d\u8d56\u4e14\u5371\u9669", "\u5b83\u4eec\u53ea\u5403\u8702\u871c", "\u770b\u5b83\u4eec\u8fdd\u6cd5", "\u5b83\u4eec\u6ca1\u6709\u7259\u9f7f"], "correct_index": 0, "explanation": "Feeding wild bears is dangerous for people and bears.", "explanation_zh": "\u5582\u98df\u91ce\u751f\u718a\u5bf9\u4eba\u548c\u718a\u90fd\u5f88\u5371\u9669\u3002"}]');
INSERT INTO "quizzes" VALUES(9,'sp_proboscis_monkey',1,'[{"question": "Where do Proboscis Monkeys live?", "question_zh": "\u957f\u9f3b\u7334\u751f\u6d3b\u5728\u54ea\u91cc\uff1f", "options": ["Deserts", "Mangroves and riverine forest of Borneo", "Mountains", "Caves"], "options_zh": ["\u6c99\u6f20", "\u5a46\u7f57\u6d32\u7684\u7ea2\u6811\u6797\u548c\u6cb3\u5cb8\u68ee\u6797", "\u5c71\u533a", "\u6d1e\u7a74"], "correct_index": 1, "explanation": "They live near rivers and mangroves in Borneo.", "explanation_zh": "\u5b83\u4eec\u751f\u6d3b\u5728\u5a46\u7f57\u6d32\u7684\u6cb3\u6d41\u548c\u7ea2\u6811\u6797\u9644\u8fd1\u3002"}, {"question": "What is special about the male''s nose?", "question_zh": "\u96c4\u7334\u7684\u9f3b\u5b50\u6709\u4ec0\u4e48\u7279\u522b\uff1f", "options": ["It is small", "It is large and may make calls louder", "It glows", "It has no nose"], "options_zh": ["\u5f88\u5c0f", "\u5f88\u5927\uff0c\u53ef\u80fd\u8ba9\u53eb\u58f0\u66f4\u54cd\u4eae", "\u4f1a\u53d1\u5149", "\u6ca1\u6709\u9f3b\u5b50"], "correct_index": 1, "explanation": "The large nose may amplify calls.", "explanation_zh": "\u5927\u9f3b\u5b50\u53ef\u80fd\u80fd\u653e\u5927\u53eb\u58f0\u3002"}, {"question": "What do Proboscis Monkeys mainly eat?", "question_zh": "\u957f\u9f3b\u7334\u4e3b\u8981\u5403\u4ec0\u4e48\uff1f", "options": ["Fish", "Leaves, seeds and unripe fruit", "Meat", "Bark only"], "options_zh": ["\u9c7c", "\u6811\u53f6\u3001\u79cd\u5b50\u548c\u672a\u6210\u719f\u679c\u5b9e", "\u8089", "\u53ea\u5403\u6811\u76ae"], "correct_index": 1, "explanation": "They are plant-eaters.", "explanation_zh": "\u5b83\u4eec\u662f\u690d\u98df\u52a8\u7269\u3002"}]');
INSERT INTO "quizzes" VALUES(10,'sp_mouse_deer',1,'[{"question": "What makes the Lesser Mouse-deer special?", "question_zh": "\u5c0f\u9f37\u9e7f\u6709\u4ec0\u4e48\u7279\u522b\uff1f", "options": ["It is huge", "It is one of the smallest hoofed animals", "It can fly", "It lives in the sea"], "options_zh": ["\u5b83\u5f88\u5927", "\u5b83\u662f\u6700\u5c0f\u7684\u6709\u8e44\u52a8\u7269\u4e4b\u4e00", "\u5b83\u4f1a\u98de", "\u5b83\u751f\u6d3b\u5728\u6d77\u91cc"], "correct_index": 1, "explanation": "It is tiny for a hoofed animal.", "explanation_zh": "\u5bf9\u6709\u8e44\u52a8\u7269\u6765\u8bf4\u5b83\u5f88\u5c0f\u3002"}, {"question": "When is the mouse-deer most active?", "question_zh": "\u5c0f\u9f37\u9e7f\u4ec0\u4e48\u65f6\u5019\u6700\u6d3b\u8dc3\uff1f", "options": ["Midday", "At night and dawn", "Only in winter", "Never"], "options_zh": ["\u4e2d\u5348", "\u591c\u95f4\u548c\u9ece\u660e", "\u53ea\u5728\u51ac\u5929", "\u4ece\u4e0d"], "correct_index": 1, "explanation": "It is shy and mostly nocturnal.", "explanation_zh": "\u5b83\u5bb3\u7f9e\u4e14\u591a\u5728\u591c\u95f4\u6d3b\u52a8\u3002"}, {"question": "What does a mouse-deer eat?", "question_zh": "\u5c0f\u9f37\u9e7f\u5403\u4ec0\u4e48\uff1f", "options": ["Leaves, fruit and fungi", "Fish", "Insects only", "Rocks"], "options_zh": ["\u6811\u53f6\u3001\u679c\u5b9e\u548c\u771f\u83cc", "\u9c7c", "\u53ea\u5403\u6606\u866b", "\u77f3\u5934"], "correct_index": 0, "explanation": "It forages for plant matter and fungi.", "explanation_zh": "\u5b83\u4ee5\u690d\u7269\u548c\u771f\u83cc\u4e3a\u98df\u3002"}]');
INSERT INTO "quizzes" VALUES(11,'sp_sunda_colugo',1,'[{"question": "How does a colugo move between trees?", "question_zh": "\u9f2f\u7334\u5982\u4f55\u5728\u6811\u95f4\u79fb\u52a8\uff1f", "options": ["It flies like a bird", "It glides using a skin membrane", "It jumps on the ground", "It swims"], "options_zh": ["\u50cf\u9e1f\u4e00\u6837\u98de", "\u7528\u76ae\u819c\u6ed1\u7fd4", "\u5728\u5730\u4e0a\u8df3", "\u6e38\u6cf3"], "correct_index": 1, "explanation": "It glides, but does not truly fly.", "explanation_zh": "\u5b83\u6ed1\u7fd4\uff0c\u4f46\u4e0d\u662f\u771f\u6b63\u98de\u884c\u3002"}, {"question": "What does a colugo eat?", "question_zh": "\u9f2f\u7334\u5403\u4ec0\u4e48\uff1f", "options": ["Leaves, flowers and fruit", "Meat", "Fish", "Honey only"], "options_zh": ["\u6811\u53f6\u3001\u82b1\u548c\u679c\u5b9e", "\u8089", "\u9c7c", "\u53ea\u5403\u8702\u871c"], "correct_index": 0, "explanation": "It is a plant-eater.", "explanation_zh": "\u5b83\u662f\u690d\u98df\u52a8\u7269\u3002"}, {"question": "What is a good time to spot a colugo?", "question_zh": "\u4ec0\u4e48\u65f6\u5019\u5bb9\u6613\u770b\u5230\u9f2f\u7334\uff1f", "options": ["Dusk, when it becomes active", "Noon", "Midnight only", "Never"], "options_zh": ["\u9ec4\u660f\uff0c\u5b83\u5f00\u59cb\u6d3b\u8dc3\u65f6", "\u4e2d\u5348", "\u53ea\u5728\u5348\u591c", "\u6c38\u8fdc\u770b\u4e0d\u5230"], "correct_index": 0, "explanation": "Colugos become active around dusk.", "explanation_zh": "\u9f2f\u7334\u5728\u9ec4\u660f\u524d\u540e\u5f00\u59cb\u6d3b\u8dc3\u3002"}]');
INSERT INTO "quizzes" VALUES(12,'sp_malayan_pangolin',1,'[{"question": "What are pangolin scales made of?", "question_zh": "\u7a7f\u5c71\u7532\u7684\u9cde\u7247\u7531\u4ec0\u4e48\u6784\u6210\uff1f", "options": ["Bone", "Keratin (like fingernails)", "Shell", "Plastic"], "options_zh": ["\u9aa8\u5934", "\u89d2\u86cb\u767d\uff08\u50cf\u6307\u7532\uff09", "\u8d1d\u58f3", "\u5851\u6599"], "correct_index": 1, "explanation": "Scales are keratin, like your nails.", "explanation_zh": "\u9cde\u7247\u662f\u89d2\u86cb\u767d\uff0c\u548c\u4f60\u7684\u6307\u7532\u4e00\u6837\u3002"}, {"question": "What do pangolins eat?", "question_zh": "\u7a7f\u5c71\u7532\u5403\u4ec0\u4e48\uff1f", "options": ["Ants and termites", "Leaves", "Fish", "Fruit"], "options_zh": ["\u8682\u8681\u548c\u767d\u8681", "\u6811\u53f6", "\u9c7c", "\u679c\u5b9e"], "correct_index": 0, "explanation": "They eat ants and termites.", "explanation_zh": "\u5b83\u4eec\u5403\u8682\u8681\u548c\u767d\u8681\u3002"}, {"question": "Why is the pangolin so threatened?", "question_zh": "\u4e3a\u4ec0\u4e48\u7a7f\u5c71\u7532\u53d7\u5230\u5982\u6b64\u4e25\u91cd\u7684\u5a01\u80c1\uff1f", "options": ["Too many predators", "Illegal wildlife trade", "It cannot find food", "Cold weather"], "options_zh": ["\u5929\u654c\u592a\u591a", "\u975e\u6cd5\u91ce\u751f\u52a8\u7269\u8d38\u6613", "\u627e\u4e0d\u5230\u98df\u7269", "\u5929\u6c14\u5bd2\u51b7"], "correct_index": 1, "explanation": "It is the world''s most trafficked mammal.", "explanation_zh": "\u5b83\u662f\u4e16\u754c\u4e0a\u88ab\u8d29\u8fd0\u6700\u591a\u7684\u54fa\u4e73\u52a8\u7269\u3002"}]');
INSERT INTO "quizzes" VALUES(13,'sp_green_sea_turtle',1,'[{"question": "What do Green Sea Turtles mainly eat?", "question_zh": "\u7eff\u6d77\u9f9f\u4e3b\u8981\u5403\u4ec0\u4e48\uff1f", "options": ["Seagrass and algae", "Fish", "Crustaceans", "Plastic"], "options_zh": ["\u6d77\u8349\u548c\u85fb\u7c7b", "\u9c7c", "\u7532\u58f3\u7c7b", "\u5851\u6599"], "correct_index": 0, "explanation": "Adults mostly eat seagrass and algae.", "explanation_zh": "\u6210\u9f9f\u4e3b\u8981\u5403\u6d77\u8349\u548c\u85fb\u7c7b\u3002"}, {"question": "Where do females lay eggs?", "question_zh": "\u96cc\u9f9f\u5728\u54ea\u91cc\u4ea7\u5375\uff1f", "options": ["In trees", "On the same beach where they hatched", "In rivers", "Underwater"], "options_zh": ["\u6811\u4e0a", "\u5728\u5b83\u51fa\u751f\u7684\u6d77\u6ee9", "\u6cb3\u91cc", "\u6c34\u4e0b"], "correct_index": 1, "explanation": "They return to their natal beach.", "explanation_zh": "\u5b83\u4eec\u4f1a\u56de\u5230\u81ea\u5df1\u7684\u51fa\u751f\u6d77\u6ee9\u3002"}, {"question": "What harms sea turtles?", "question_zh": "\u4ec0\u4e48\u4f1a\u4f24\u5bb3\u6d77\u9f9f\uff1f", "options": ["Plastic pollution and habitat loss", "Too much seagrass", "Rain", "Wind"], "options_zh": ["\u5851\u6599\u6c61\u67d3\u548c\u6816\u606f\u5730\u4e27\u5931", "\u6d77\u8349\u592a\u591a", "\u4e0b\u96e8", "\u98ce"], "correct_index": 0, "explanation": "Pollution and beach loss are major threats.", "explanation_zh": "\u6c61\u67d3\u548c\u6d77\u6ee9\u4e27\u5931\u662f\u4e3b\u8981\u5a01\u80c1\u3002"}]');
INSERT INTO "quizzes" VALUES(14,'sp_reticulated_python',1,'[{"question": "What is the Reticulated Python known for?", "question_zh": "\u7f51\u7eb9\u87d2\u4ee5\u4ec0\u4e48\u8457\u79f0\uff1f", "options": ["Being one of the longest snakes", "Being venomous and deadly", "Living in the sea", "Flying"], "options_zh": ["\u6700\u957f\u7684\u86c7\u4e4b\u4e00", "\u5267\u6bd2\u81f4\u547d", "\u751f\u6d3b\u5728\u6d77\u91cc", "\u4f1a\u98de"], "correct_index": 0, "explanation": "It is among the world''s longest snakes.", "explanation_zh": "\u5b83\u662f\u4e16\u754c\u4e0a\u6700\u957f\u7684\u86c7\u4e4b\u4e00\u3002"}, {"question": "What should you do if you see a python?", "question_zh": "\u770b\u5230\u87d2\u86c7\u5e94\u8be5\u600e\u4e48\u505a\uff1f", "options": ["Pick it up", "Admire from a safe distance and never provoke it", "Throw things", "Chase it"], "options_zh": ["\u6361\u8d77\u6765", "\u5728\u5b89\u5168\u8ddd\u79bb\u5916\u6b23\u8d4f\uff0c\u7edd\u4e0d\u6311\u9017", "\u6254\u4e1c\u897f", "\u8ffd\u5b83"], "correct_index": 1, "explanation": "Never pick up or provoke a snake.", "explanation_zh": "\u7edd\u4e0d\u6361\u8d77\u6216\u6311\u9017\u86c7\u3002"}, {"question": "Where does the reticulated python often live?", "question_zh": "\u7f51\u7eb9\u87d2\u5e38\u751f\u6d3b\u5728\u54ea\u91cc\uff1f", "options": ["Near rivers and forest", "Deserts", "Mountain peaks", "Open ocean"], "options_zh": ["\u6cb3\u6d41\u548c\u68ee\u6797\u9644\u8fd1", "\u6c99\u6f20", "\u5c71\u9876", "\u5f00\u9614\u6d77\u57df"], "correct_index": 0, "explanation": "It is often found near water.", "explanation_zh": "\u5b83\u5e38\u5728\u6c34\u57df\u9644\u8fd1\u88ab\u53d1\u73b0\u3002"}]');
INSERT INTO "quizzes" VALUES(15,'sp_saltwater_crocodile',1,'[{"question": "What is the Saltwater Crocodile?", "question_zh": "\u6e7e\u9cc4\u662f\u4ec0\u4e48\uff1f", "options": ["The largest living reptile", "A small lizard", "A fish", "A bird"], "options_zh": ["\u73b0\u5b58\u6700\u5927\u7684\u722c\u884c\u52a8\u7269", "\u4e00\u79cd\u5c0f\u8725\u8734", "\u4e00\u79cd\u9c7c", "\u4e00\u79cd\u9e1f"], "correct_index": 0, "explanation": "It is the largest living reptile.", "explanation_zh": "\u5b83\u662f\u73b0\u5b58\u6700\u5927\u7684\u722c\u884c\u52a8\u7269\u3002"}, {"question": "Where do saltwater crocodiles live?", "question_zh": "\u6e7e\u9cc4\u751f\u6d3b\u5728\u54ea\u91cc\uff1f", "options": ["Rivers, estuaries and mangroves", "Deserts", "Caves", "Mountains"], "options_zh": ["\u6cb3\u6d41\u3001\u6cb3\u53e3\u548c\u7ea2\u6811\u6797", "\u6c99\u6f20", "\u6d1e\u7a74", "\u5c71\u533a"], "correct_index": 0, "explanation": "They live in coastal and river habitats.", "explanation_zh": "\u5b83\u4eec\u751f\u6d3b\u5728\u6cbf\u6d77\u548c\u6cb3\u6d41\u6816\u606f\u5730\u3002"}, {"question": "What should you do in crocodile areas?", "question_zh": "\u5728\u9cc4\u9c7c\u51fa\u6ca1\u533a\u5e94\u8be5\u600e\u4e48\u505a\uff1f", "options": ["Stay away from river edges and follow signs", "Swim often", "Feed them", "Approach quietly"], "options_zh": ["\u8fdc\u79bb\u6cb3\u8fb9\u5e76\u9075\u5b88\u6807\u5fd7", "\u7ecf\u5e38\u6e38\u6cf3", "\u5582\u5b83\u4eec", "\u6084\u6084\u9760\u8fd1"], "correct_index": 0, "explanation": "Follow local signs and keep away from the water''s edge.", "explanation_zh": "\u9075\u5b88\u5f53\u5730\u6807\u5fd7\uff0c\u8fdc\u79bb\u6c34\u8fb9\u3002"}]');
INSERT INTO "species" VALUES('sp_common_mormon','Common Mormon','Papilio polytes','Butterfly','Gardens, parks and forest edges across Malaysia.','Adults drink flower nectar; caterpillars eat the leaves of citrus plants.','Habitat loss and the use of pesticides in gardens.','Not threatened','Some females copy the look of a poisonous butterfly to scare away predators.','Watch it feed without touching its wings — they are delicate.','WildQuest curated content','seed v0.1 (placeholder — pending cited sources)',0,'🦋','/img/species/sp_common_mormon.jpg','玉带凤蝶','Black swallowtail butterfly with white spots; females may mimic the poisonous Common Rose.','马来西亚的花园、公园和森林边缘。','成虫吸食花蜜；幼虫取食柑橘类植物的叶子。','栖息地丧失和花园中农药的使用。','部分雌蝶会模仿有毒蝴蝶的外貌，以吓退天敌。','观察它进食时不要触碰翅膀——翅膀很脆弱。','','');
INSERT INTO "species" VALUES('sp_tailed_jay','Tailed Jay','Graphium agamemnon','Butterfly','Gardens, orchards and lowland forests.','Adults drink nectar from flowers.','Habitat loss and pesticide use.','Not threatened','It is one of the fastest-flying butterflies and is green with black spots.','Let it settle before you photograph it — no need to chase.','WildQuest curated content','seed v0.1 (placeholder — pending cited sources)',0,'🦋','/img/species/sp_tailed_jay.jpg','统帅青凤蝶','Green butterfly with black spots and small tails on the hindwings.','花园、果园和低地森林。','成虫吸食花蜜。','栖息地丧失和农药使用。','它是飞行最快的蝴蝶之一，翅膀绿色带黑斑。','等它停稳再拍照——不必追逐。','','');
INSERT INTO "species" VALUES('sp_oriental_pied_hornbill','Oriental Pied Hornbill','Anthracoceros albirostris','Bird','Lowland forests, forest edges and gardens.','Fruit (especially figs), insects and small animals.','Forest loss and the removal of old trees with nesting holes.','Least Concern','The female seals herself inside a tree cavity to lay eggs, leaving a small gap for food.','Listen for its flapping call and watch from a distance.','WildQuest curated content','seed v0.1 (placeholder — pending cited sources)',0,'🐦','/img/species/sp_oriental_pied_hornbill.jpg','冠斑犀鸟','Black-and-white bird with a large pale yellow bill and casque.','低地森林、森林边缘和花园。','果实（尤其是无花果）、昆虫和小型动物。','森林丧失以及有筑巢洞的老树被砍伐。','雌鸟会把自己封在树洞里产卵，只留一个小口取食。','听它拍翅的叫声，在远处观察。','','');
INSERT INTO "species" VALUES('sp_rhinoceros_hornbill','Rhinoceros Hornbill','Buceros rhinoceros','Bird','Lowland and hill rainforest, especially old-growth forest.','Fruit (mainly figs), insects and small animals.','Forest loss and hunting for feathers and the casque.','Vulnerable','It is the state bird of Sarawak and has a bright orange casque on its bill.','Report sightings without sharing exact nest locations.','WildQuest curated content','seed v0.1 (placeholder — pending cited sources)',1,'🦜','/img/species/sp_rhinoceros_hornbill.jpg','马来犀鸟','Large black bird with a bright orange-red casque on the bill and a white tail.','低地和山地雨林，尤其是原始林。','果实（主要是无花果）、昆虫和小型动物。','森林丧失以及为羽毛和盔突而进行的捕猎。','它是砂拉越州的州鸟，喙上有醒目的橙色盔突。','报告目击时不要公开确切的巢穴位置。','','');
INSERT INTO "species" VALUES('sp_asian_elephant','Asian Elephant','Elephas maximus','Mammal','Lowland and hill forest across Peninsular Malaysia and Borneo.','Grasses, leaves, bark and fruit.','Habitat loss and conflict with farms and plantations.','Endangered','They use their trunk to smell, drink, greet and pick up food.','Keep far away and never block their path — they are wild animals.','GBIF','https://cloud.gbif.org/asia/resource?r=bifa5_006',1,'🐘','/img/species/sp_asian_elephant.jpg','亚洲象','Large grey mammal with a long trunk and large ears, smaller than the African elephant.','马来西亚半岛和婆罗洲的低地与山地森林。','草、树叶、树皮和果实。','栖息地丧失以及与农田和种植园的冲突。','它们用象鼻来闻、喝水、打招呼和取食。','保持很远距离，绝不挡住它的去路——它们是野生动物。','Second Schedule','Totally Protected');
INSERT INTO "species" VALUES('sp_malayan_tiger','Malayan Tiger','Panthera tigris jacksoni','Mammal','Tropical forest, mainly in the central forest spine.','Deer, wild boar and other medium-sized animals.','Poaching, habitat loss and decline of prey.','Critically Endangered','Each tiger has a unique stripe pattern, like a fingerprint.','Tigers are rare and shy — never try to find or approach one.','GBIF','https://cloud.gbif.org/asia/resource?r=bifa5_006',1,'🐅','/img/species/sp_malayan_tiger.jpg','马来亚虎','Large orange cat with narrow black stripes.','热带森林，主要分布在中部森林脊柱。','鹿、野猪和其他中型动物。','盗猎、栖息地丧失和猎物减少。','每只老虎的条纹都是独一无二的，就像指纹。','老虎稀有而害羞——千万不要去寻找或靠近。','Second Schedule','Totally Protected');
INSERT INTO "species" VALUES('sp_malayan_tapir','Malayan Tapir','Tapirus indicus','Mammal','Rainforest, often near water.','Leaves, shoots and fruit.','Habitat loss and road accidents.','Endangered','Babies are born with stripes and spots that fade as they grow.','If you see one, keep your distance and move quietly away.','GBIF','https://cloud.gbif.org/asia/resource?r=bifa5_006',1,'🦏','/img/species/sp_malayan_tapir.jpg','马来貘','Black body with a broad white saddle across the middle and a short trunk-like snout.','雨林，常靠近水源。','树叶、嫩枝和果实。','栖息地丧失和交通事故。','幼崽出生时带条纹和斑点，长大后逐渐褪去。','如果看到它，保持距离并安静离开。','','');
INSERT INTO "species" VALUES('sp_sun_bear','Malayan Sun Bear','Helarctos malayanus','Mammal','Tropical forest, spending much time in trees.','Insects, honey, fruit and small animals.','Habitat loss and the illegal pet trade.','Vulnerable','It is the world''s smallest bear and has a pale horseshoe mark on its chest.','Never feed a sun bear — it can become dependent and dangerous.','GBIF','https://cloud.gbif.org/asia/resource?r=bifa5_006',1,'🐻','/img/species/sp_sun_bear.jpg','马来熊','Small black bear with a pale orange horseshoe-shaped mark on the chest.','热带森林，大部分时间待在树上。','昆虫、蜂蜜、果实和小型动物。','栖息地丧失和非法宠物贸易。','它是世界上最小的熊，胸前有淡色马蹄形斑纹。','绝不要投喂马来熊——它会变得依赖且危险。','Second Schedule','Totally Protected');
INSERT INTO "species" VALUES('sp_proboscis_monkey','Proboscis Monkey','Nasalis larvatus','Mammal','Mangroves and riverine forest of Borneo.','Leaves, seeds and unripe fruit.','Habitat loss along rivers and mangroves.','Endangered','The male''s large nose is thought to make its calls louder.','Watch quietly from a boat or trail without disturbing the troop.','WildQuest curated content','seed v0.1 (placeholder — pending cited sources)',1,'🐒','/img/species/sp_proboscis_monkey.jpg','长鼻猴','Reddish-brown monkey with a very large fleshy nose, especially in males.','婆罗洲的红树林和河岸森林。','树叶、种子和未成熟果实。','沿河和红树林的栖息地丧失。','雄猴的大鼻子被认为能让叫声更响亮。','在船上或小径上安静观察，不要惊扰猴群。','','');
INSERT INTO "species" VALUES('sp_mouse_deer','Lesser Mouse-deer','Tragulus kanchil','Mammal','Dense forest undergrowth.','Leaves, fruit and fungi.','Habitat loss and hunting.','Least Concern','It is one of the smallest hoofed animals in the world.','It is shy and mostly active at night — a rare, lucky sighting.','GBIF','https://cloud.gbif.org/asia/resource?r=bifa5_006',0,'🦌','/img/species/sp_mouse_deer.jpg','小鼷鹿','Tiny brown hoofed animal with thin legs, about the size of a rabbit.','茂密的森林下层。','树叶、果实和真菌。','栖息地丧失和捕猎。','它是世界上最小的有蹄动物之一。','它害羞且多在夜间活动——能见到是很幸运的。','','');
INSERT INTO "species" VALUES('sp_sunda_colugo','Sunda Colugo','Galeopterus variegatus','Mammal','Rainforest canopy, including gardens near forest.','Leaves, flowers and fruit.','Forest loss.','Least Concern','It glides between trees using a skin membrane — it does not truly fly.','Look up quietly at dusk when colugos become active.','WildQuest curated content','seed v0.1 (placeholder — pending cited sources)',0,'🦇','/img/species/sp_sunda_colugo.jpg','巽他鼯猴','Grey-brown furred mammal with a large gliding membrane between its limbs.','雨林树冠，包括森林附近的花园。','树叶、花和果实。','森林丧失。','它用皮膜在树间滑翔——并不是真正飞行。','黄昏时分安静地抬头观察，那时鼯猴开始活跃。','Second Schedule','Totally Protected');
INSERT INTO "species" VALUES('sp_malayan_pangolin','Malayan Pangolin','Manis javanica','Mammal','Forest and sometimes plantations.','Ants and termites.','Illegal wildlife trade — it is the world''s most trafficked mammal.','Critically Endangered','Its scales are made of keratin, the same material as your fingernails.','Never reveal where you saw a pangolin — this protects it from poachers.','GBIF','https://cloud.gbif.org/asia/resource?r=bifa5_006',1,'🦔','/img/species/sp_malayan_pangolin.jpg','马来穿山甲','Brown mammal covered in overlapping scales that curls into a ball when threatened.','森林，有时也在种植园。','蚂蚁和白蚁。','非法野生动物贸易——它是世界上被贩运最多的哺乳动物。','它的鳞片由角蛋白构成，和你的指甲是同样的材料。','绝不要透露穿山甲的位置——这能保护它免受盗猎。','','');
INSERT INTO "species" VALUES('sp_green_sea_turtle','Green Sea Turtle','Chelonia mydas','Reptile','Coastal waters, seagrass beds and nesting beaches.','Seagrass and algae.','Habitat loss, plastic pollution and poaching of eggs.','Endangered','Females return to the same beach where they hatched to lay their own eggs.','Watch nesting turtles only with a guide and never use bright lights.','WildQuest curated content','seed v0.1 (placeholder — pending cited sources)',1,'🐢','/img/species/sp_green_sea_turtle.jpg','绿海龟','Large sea turtle with a smooth olive-green shell and paddle-like flippers.','沿海水域、海草床和产卵海滩。','海草和藻类。','栖息地丧失、塑料污染和盗取龟蛋。','雌龟会回到自己出生的海滩产卵。','只在向导带领下观察产卵海龟，绝不用强光。','','');
INSERT INTO "species" VALUES('sp_reticulated_python','Reticulated Python','Malayopython reticulatus','Reptile','Forest, often near rivers and water.','Mammals and birds.','Hunting for skin and the pet trade.','Least Concern (protected in Malaysia)','It is one of the longest snakes in the world.','Admire from a safe distance — never pick up or provoke a snake.','WildQuest curated content','seed v0.1 (placeholder — pending cited sources)',0,'🐍','/img/species/sp_reticulated_python.jpg','网纹蟒','Very long snake with an intricate net-like pattern of dark diamonds.','森林，常靠近河流和水域。','哺乳动物和鸟类。','为获取蛇皮和宠物贸易而进行的捕猎。','它是世界上最长的蛇之一。','在安全距离外欣赏——绝不捡起或挑逗蛇。','','');
INSERT INTO "species" VALUES('sp_saltwater_crocodile','Saltwater Crocodile','Crocodylus porosus','Reptile','Rivers, estuaries and mangroves.','Fish, crustaceans and mammals.','Habitat loss and historical hunting.','Least Concern','It is the largest living reptile.','Stay away from river edges in crocodile areas and follow local signs.','WildQuest curated content','seed v0.1 (placeholder — pending cited sources)',0,'🐊','/img/species/sp_saltwater_crocodile.jpg','湾鳄','Very large grey-brown reptile with a broad snout and bony ridges on the back.','河流、河口和红树林。','鱼、甲壳类和哺乳动物。','栖息地丧失和历史上的捕猎。','它是现存最大的爬行动物。','在鳄鱼出没区远离河边并遵守当地标志。','','');
